/* Rajdhani — SIL Open Font License 1.1, google/fonts ofl/rajdhani */
@font-face {
  font-family: "Rajdhani";
  font-style: normal;
  font-weight: 700 900;
  font-display: swap;
  src: url(data:font/ttf;base64,)
    format("truetype");
}
/* Nunito — SIL Open Font License 1.1, google/fonts ofl/nunito */
@font-face {
  font-family: "Nunito";
  font-style: normal;
  font-weight: 200 1000;
  font-display: swap;
  src: url(data:font/ttf;base64,)
    format("truetype");
}
/* DARK SHY — Atelier / Premium glass visual system */
:root {
  --bg: #0d0d1a;
  --pink: #ff6b9d;
  --pink-soft: #ff8fb4;
  --purple: #c44dff;
  --gold: #ffd700;
  --cyan: #00d4ff;
  --text: #fff;
  --muted: #aaaacc;
  --ease: cubic-bezier(0.4, 0, 0.2, 1);
  --spring: cubic-bezier(0.2, 0.85, 0.25, 1.12);
  --hud: 100px;
  --footer: 112px;
  --font: "Nunito", system-ui, sans-serif;
  --num: "Rajdhani", sans-serif;
  --shadow: 0 4px 20px #0005, 0 0 18px #ff6b9d0d;
}
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
  scrollbar-width: thin;
  scrollbar-color: #a55082 #101023;
}
html,
body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  overscroll-behavior: none;
}
body {
  position: fixed;
  inset: 0;
  background: radial-gradient(ellipse at 50% 30%, #302045, #0d0d1a 70%);
  font: 14px/1.5 var(--font);
  color: var(--text);
  user-select: none;
  -webkit-touch-callout: none;
}
button,
input {
  font: inherit;
  color: inherit;
}
button {
  position: relative;
  min-height: 44px;
  border: 1px solid #ffffff12;
  border-radius: 16px;
  cursor: pointer;
  background: linear-gradient(145deg, #ffffff12, #ffffff05);
  box-shadow:
    inset 0 1px #ffffff0f,
    var(--shadow);
  transition:
    transform 0.24s var(--ease),
    box-shadow 0.24s var(--ease),
    background 0.24s var(--ease),
    opacity 0.24s var(--ease);
}
button:disabled {
  cursor: not-allowed;
  opacity: 0.4;
  filter: saturate(0.25);
}
button:active:not(:disabled) {
  transform: scale(0.94);
  box-shadow:
    inset 0 2px 8px #0005,
    0 0 22px #ff6b9d44;
}
button:focus-visible,
[tabindex]:focus-visible,
input:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 4px;
}
img {
  display: block;
  max-width: 100%;
  pointer-events: none;
}
b,
strong {
  font-weight: 800;
}
small {
  font-size: 11px;
  color: var(--muted);
}
.hidden {
  display: none !important;
}
.dim {
  opacity: 0.5;
}
::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}
::-webkit-scrollbar-track {
  background: #101023;
  border-radius: 20px;
}
::-webkit-scrollbar-thumb {
  background: linear-gradient(var(--pink), #833c9f);
  border-radius: 20px;
}
@media (hover: hover) and (pointer: fine) {
  button:not(:disabled):hover {
    transform: translateY(-2px) scale(1.025);
    box-shadow:
      inset 0 1px #ffffff22,
      0 6px 24px #0005,
      0 0 18px #ff6b9d30;
  }
  button:not(:disabled):active {
    transform: scale(0.94);
  }
  .up-item:hover {
    background: linear-gradient(120deg, #ffffff0f, #ffffff06);
  }
  .costume-thumb:hover,
  .inv-item:hover {
    transform: translateY(-3px);
    box-shadow: 0 0 20px #ff6b9d44;
  }
}
/* HUD */
#hud {
  position: fixed;
  inset: 0 0 auto;
  height: calc(var(--hud) + env(safe-area-inset-top));
  padding: calc(18px + env(safe-area-inset-top))
    max(28px, env(safe-area-inset-right)) 18px
    max(28px, env(safe-area-inset-left));
  display: flex;
  align-items: center;
  gap: 32px;
  z-index: 30;
  background: linear-gradient(180deg, #0d0d1af5, #0d0d1ab3);
  backdrop-filter: blur(16px);
  box-shadow: 0 8px 30px #0003;
  animation: hudEnter 0.7s var(--ease) both;
}
#hud:after,
#bottom-bar:before {
  content: "";
  position: absolute;
  height: 1px;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(
    90deg,
    transparent,
    #ff6b9d77,
    #c44dff44,
    transparent
  );
}
.hud-left {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-shrink: 0;
}
.avatar-ring {
  position: relative;
  width: 48px;
  height: 48px;
  padding: 2px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--pink), var(--purple));
  box-shadow:
    0 0 20px #ff6b9d33,
    inset 0 0 10px #ff6b9d44;
}
.avatar-ring img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 6%;
  border-radius: 50%;
  background: linear-gradient(140deg, #31203e, #0f1026);
}
.hud-lv {
  position: absolute;
  right: -6px;
  bottom: -5px;
  min-width: 23px;
  height: 23px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: linear-gradient(145deg, #fff3a0, #ffaa00);
  color: #37200a;
  font: 700 15px var(--num);
  box-shadow: 0 2px 8px #0006;
}
.hud-name {
  font-size: 16px;
  font-weight: 900;
  letter-spacing: 1px;
  background: linear-gradient(120deg, #fff, var(--pink-soft));
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
.hud-title {
  display: block;
  font-size: 10px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--muted);
  -webkit-text-fill-color: var(--muted);
}
.hud-caption {
  font-size: 9px;
  letter-spacing: 2.5px;
  color: var(--muted);
  margin-bottom: 3px;
}
.hud-center {
  width: 280px;
  max-width: 30vw;
  min-width: 100px;
  margin-left: auto;
}
.heart-label {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  margin-bottom: 8px;
  color: var(--pink-soft);
}
.heart-bar {
  position: relative;
  height: 24px;
  border-radius: 999px;
  background: linear-gradient(180deg, #070717, #22203b);
  box-shadow:
    inset 0 2px 7px #0009,
    0 0 12px #ff6b9d22;
  overflow: hidden;
  border: 1px solid #ff6b9d30;
}
.heart-bar:before {
  content: "♥";
  position: absolute;
  left: 10px;
  top: 1px;
  z-index: 3;
  font-size: 14px;
  color: #fff0f7;
  text-shadow: 0 0 8px var(--pink);
}
#heart-fill {
  position: absolute;
  inset: 0;
  width: 100%;
  transform-origin: left;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--pink), #ff3d7f);
  box-shadow: 0 0 12px #ff6b9d66;
  transition: transform 0.5s var(--ease);
}
#heart-fill:after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    105deg,
    transparent 30%,
    #ffffff66 50%,
    transparent 70%
  );
  animation: shimmer 4s ease-in-out infinite;
}
.bar-level {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  font: 700 14px var(--num);
  text-shadow: 0 1px 4px #000a;
}
.heart-xp {
  text-align: right;
  margin-top: 4px;
  font: 700 11px var(--num);
  color: var(--muted);
}
.hud-right {
  display: flex;
  gap: 10px;
  align-items: center;
}
.chip {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 90px;
  padding: 8px 14px;
  border-radius: 999px;
  border: 1px solid #ffffff14;
  background: linear-gradient(145deg, #ffffff0f, #ffffff04);
  box-shadow:
    inset 0 2px 6px #0004,
    0 3px 12px #0002;
  white-space: nowrap;
  font-size: 15px;
}
.chip span {
  font: 700 21px var(--num);
  font-variant-numeric: tabular-nums;
}
.chip-coins {
  color: var(--gold);
}
.chip-gems {
  color: #db98ff;
}
.chip-energy {
  color: var(--cyan);
}
.chip small {
  font: 700 10px var(--num);
}
.hud-actions {
  display: flex;
  gap: 8px;
}
.circle-btn {
  height: 42px;
  width: 42px;
  min-height: 42px;
  border-radius: 50%;
  background:
    linear-gradient(#1b1933, #151327) padding-box,
    linear-gradient(135deg, #ff6b9d66, #c44dff22) border-box;
  border: 1px solid transparent;
  color: #dbd5eb;
}
.notification-dot {
  position: absolute;
  right: 7px;
  top: 7px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #ff4466;
  box-shadow: 0 0 8px #ff4466;
  animation: dotPulse 2s infinite;
}
#save-flash {
  position: fixed;
  top: calc(var(--hud) + env(safe-area-inset-top) + 7px);
  right: 28px;
  font-size: 9px;
  letter-spacing: 2px;
  color: #a4f6d0;
  text-transform: uppercase;
  opacity: 0;
  transition: opacity 0.25s;
}
#save-flash.show {
  opacity: 1;
}
/* Living stage */
#stage {
  position: absolute;
  top: calc(var(--hud) + env(safe-area-inset-top));
  bottom: calc(var(--footer) + env(safe-area-inset-bottom));
  left: 0;
  right: 0;
  isolation: isolate;
  overflow: hidden;
}
.bg-layer {
  position: absolute;
  inset: -15px;
  background-size: cover;
  background-position: center;
  opacity: 0;
  transition: opacity 1.2s var(--ease);
  filter: brightness(0.69) saturate(0.8);
  z-index: -5;
}
.bg-layer.show {
  opacity: 1;
}
.bg-vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: -4;
  background:
    linear-gradient(
      90deg,
      #0d0d1ac4,
      transparent 32%,
      transparent 65%,
      #0d0d1ac9
    ),
    linear-gradient(
      0deg,
      #0d0d1add,
      transparent 25%,
      transparent 75%,
      #0d0d1a55
    );
}
.stage-caption {
  position: absolute;
  left: 50%;
  top: 22px;
  transform: translateX(-50%);
  text-align: center;
  pointer-events: none;
  color: #ffffff60;
  font-size: 9px;
  letter-spacing: 4px;
  text-transform: uppercase;
  white-space: nowrap;
}
.stage-caption b {
  display: block;
  color: #ffffffaa;
  letter-spacing: 2px;
  font-size: 12px;
  margin-top: 4px;
}
.stage-corner {
  position: absolute;
  left: 260px;
  bottom: 25px;
  color: #ffffff55;
  letter-spacing: 2px;
  font-size: 9px;
}
.stage-corner span {
  display: block;
  color: #ffb7d2;
  font-size: 11px;
  letter-spacing: 1px;
  margin-top: 3px;
}
#character-wrap {
  position: absolute;
  left: 50%;
  bottom: 0;
  transform: translateX(-50%);
  width: min(44vw, 460px);
  height: 94%;
  cursor: pointer;
  touch-action: none;
  z-index: 4;
  animation: characterEnter 1s var(--ease) both;
}
#character-wrap:before {
  content: "";
  position: absolute;
  inset: 15% -30% 5%;
  border-radius: 50%;
  background: radial-gradient(ellipse, #ff6b9d44, transparent 65%);
  filter: blur(45px);
  pointer-events: none;
  z-index: -1;
}
.character-stack {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity 0.8s var(--ease);
  pointer-events: none;
  z-index: 2;
}
.character-stack.show {
  opacity: 1;
}
.layer {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: bottom;
  will-change: transform;
  filter: drop-shadow(0 8px 12px #0006);
}
.character-single,
.char-breathe {
  animation: breathe 4s ease-in-out infinite;
  transform-origin: center bottom;
}
.ssr-anim .layer {
  animation:
    breathe 3s ease-in-out infinite,
    glow 2s ease-in-out infinite;
}
.char-tap .character-stack.show {
  animation: tapReact 0.3s ease-out;
}
#char-shadow {
  position: absolute;
  left: 20%;
  right: 20%;
  bottom: 0;
  height: 23px;
  background: radial-gradient(ellipse, #000c, transparent 70%);
  border-radius: 50%;
  filter: blur(7px);
  z-index: 1;
  transition: transform 0.2s;
}
#char-shadow.pop {
  transform: scale(1.16);
}
#bubble {
  position: absolute;
  left: 75%;
  bottom: 64%;
  width: 230px;
  padding: 18px 20px 18px 43px;
  border-radius: 16px 16px 16px 4px;
  border: 1px solid #ffa8cf33;
  background: linear-gradient(145deg, #262239e8, #17172bd9);
  backdrop-filter: blur(16px);
  box-shadow:
    0 8px 30px #0005,
    0 0 20px #ff6b9d0d,
    inset 0 1px #ffffff15;
  opacity: 0;
  transform: translateY(10px);
  transition:
    opacity 0.25s,
    transform 0.25s;
  pointer-events: none;
  font-size: 13px;
  font-style: italic;
  text-shadow: 0 0 12px #ff6b9d33;
  z-index: 7;
}
#bubble:before {
  content: "B";
  position: absolute;
  left: 10px;
  top: 14px;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, #ff6b9d, #8e45a8);
  font: 800 11px var(--font);
  box-shadow: 0 0 12px #ff6b9d33;
}
#bubble.show {
  opacity: 1;
  transform: translateY(0);
}
.bubble-tail {
  display: none;
}
#boost-pill {
  position: absolute;
  bottom: 22px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 12;
  padding: 8px 20px;
  border-radius: 999px;
  background: linear-gradient(120deg, #544323ee, #271a3dee);
  border: 1px solid #ffd70044;
  box-shadow: 0 0 25px #ffd70022;
  color: var(--gold);
  font: 700 18px var(--num);
}
#boost-pill small {
  margin-left: 8px;
}
/* Navigation */
.rail-toggle {
  position: absolute;
  top: 22px;
  left: 20px;
  width: 44px;
  height: 44px;
  z-index: 22;
  display: none;
  border-radius: 50%;
  backdrop-filter: blur(16px);
}
.rail-toggle.right {
  left: auto;
  right: 20px;
}
.rail-backdrop {
  position: absolute;
  inset: 0;
  z-index: 19;
  background: #03031088;
  backdrop-filter: blur(5px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s;
}
.rail-backdrop.visible {
  opacity: 1;
  pointer-events: auto;
}
#left-rail,
#right-rail {
  position: absolute;
  z-index: 21;
  top: 24px;
  bottom: 24px;
  padding: 20px;
  border-radius: 24px;
  background: linear-gradient(150deg, #18182bcc, #101021b3);
  border: 1px solid #ffffff0c;
  backdrop-filter: blur(20px);
  box-shadow:
    0 12px 40px #0004,
    inset 0 1px #ffffff0a;
  transition: transform 0.35s var(--spring);
  overflow: auto;
}
#left-rail {
  left: 24px;
  width: 202px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  animation: railEnter 0.7s var(--ease) both;
}
#left-rail:after {
  content: "";
  position: absolute;
  right: 0;
  top: 15%;
  bottom: 15%;
  width: 1px;
  background: linear-gradient(transparent, #ff6b9d55, transparent);
}
.rail-heading {
  font-size: 9px;
  letter-spacing: 2.5px;
  color: #a399b8;
  text-transform: uppercase;
  padding: 0 5px 12px;
}
.rail-heading b {
  display: block;
  color: white;
  font-size: 16px;
  letter-spacing: 1px;
  margin-top: 4px;
}
.rail-btn {
  display: flex;
  align-items: center;
  gap: 13px;
  text-align: left;
  min-height: 58px;
  padding: 9px 12px;
  border-radius: 14px;
  border: 1px solid #ffffff06;
  background: linear-gradient(125deg, #ffffff08, #ffffff02);
  box-shadow: inset 0 1px #ffffff04;
  color: #d6cfe4;
  font-size: 12px;
  font-weight: 700;
}
.rail-btn .ico {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  flex-shrink: 0;
  background: linear-gradient(140deg, #ff6b9d25, #c44dff1a);
  box-shadow: inset 0 1px #ffffff12;
  font-size: 17px;
}
.rail-btn[data-modal="gacha"] {
  background: linear-gradient(110deg, #ff6b9d1c, #c44dff10);
  box-shadow:
    inset 3px 0 #ff6b9d,
    0 0 20px #ff6b9d08;
  color: #ffd7e8;
}
.rail-foot {
  margin-top: auto;
  padding: 16px 4px 0;
  font-size: 9px;
  letter-spacing: 1.7px;
  color: #7b7594;
}
.rail-foot span {
  color: #ff6b9d;
}
#right-rail {
  right: 24px;
  width: 144px;
  padding: 14px;
  animation: railEnterRight 0.7s var(--ease) both;
}
.rail-head {
  font-size: 9px;
  letter-spacing: 2px;
  text-align: center;
  color: #ddd3e7;
  margin: 4px 0 16px;
}
.rail-head small {
  display: block;
  font-size: 8px;
  color: #78728e;
  margin-top: 4px;
  letter-spacing: 1px;
}
#costume-list {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
  padding: 4px;
}
.costume-thumb {
  position: relative;
  height: 120px;
  min-width: 0;
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid #ffffff26;
  background:
    radial-gradient(ellipse at top, #5d596b55, transparent),
    linear-gradient(145deg, #242139, #131321);
  box-shadow:
    0 4px 14px #0004,
    inset 0 1px #ffffff16;
  cursor: pointer;
  transition:
    transform 0.25s,
    box-shadow 0.25s;
}
.costume-thumb:after {
  content: "";
  position: absolute;
  inset: 30% 0 0;
  background: linear-gradient(transparent, #0a0916ef);
  pointer-events: none;
}
.costume-thumb img {
  height: 100%;
  width: 100%;
  object-fit: contain;
  object-position: center 15%;
  transition: filter 0.3s;
}
.costume-thumb .rar {
  position: absolute;
  top: 7px;
  left: 7px;
  z-index: 3;
  font-size: 8px;
  padding: 1px 6px;
  border-radius: 999px;
  background: #0d0d1ac9;
}
.costume-thumb:has(.R) {
  border-color: #60b8ff66;
}
.costume-thumb:has(.SR) {
  border-color: #c44dff88;
  box-shadow: 0 0 15px #c44dff16;
}
.costume-thumb:has(.SSR) {
  border-color: #ffd70077;
  animation: rareGlow 3s infinite;
}
.costume-thumb.locked img {
  filter: brightness(0.15) blur(1px);
}
.lock {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  z-index: 4;
  font-size: 18px;
  text-shadow: 0 0 12px #000;
}
.costume-thumb.equipped {
  border-color: var(--pink);
  transform: scale(1.04);
  box-shadow:
    0 0 16px #ff6b9d55,
    inset 0 0 10px #ff6b9d22;
}
.costume-name {
  position: absolute;
  bottom: 8px;
  left: 5px;
  right: 5px;
  text-align: center;
  font-size: 8px;
  line-height: 1.2;
  color: #eee6f4;
  z-index: 3;
}
.costume-thumb.locked .costume-name {
  color: #aaa0ba;
}
.rar {
  font: 800 11px var(--num);
  letter-spacing: 1px;
}
.rar.N {
  color: #c6c5d5;
}
.rar.R {
  color: #6bb6ff;
}
.rar.SR {
  color: #d992ff;
}
.rar.SSR {
  color: var(--gold);
}
/* Bottom console */
#bottom-bar {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  height: calc(var(--footer) + env(safe-area-inset-bottom));
  padding: 18px max(32px, env(safe-area-inset-right))
    calc(18px + env(safe-area-inset-bottom))
    max(32px, env(safe-area-inset-left));
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 40px;
  background: linear-gradient(0deg, #0d0d1afa, #151325db);
  backdrop-filter: blur(20px);
  box-shadow: 0 -10px 40px #0004;
  z-index: 28;
  animation: footerEnter 0.65s var(--ease) both;
}
#bottom-bar:before {
  top: 0;
  bottom: auto;
}
.bb-left,
.bb-right {
  display: flex;
  align-items: center;
  gap: 14px;
  flex: 1;
}
.bb-right {
  justify-content: flex-end;
}
.bb-btn {
  width: 54px;
  height: 54px;
  min-height: 48px;
  border-radius: 50%;
  font-size: 18px;
  background:
    linear-gradient(#201b34, #141226) padding-box,
    linear-gradient(135deg, #ff6b9d66, #c44dff22) border-box;
  border: 1px solid transparent;
}
.bb-btn .button-caption {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  margin-top: 3px;
  font-size: 8px;
  white-space: nowrap;
  letter-spacing: 1px;
  color: #aaa0ba;
}
.bb-btn.on {
  box-shadow: 0 0 14px #00ff8814;
}
.bb-btn b {
  font-size: 9px;
}
.bb-stat {
  padding: 7px 14px;
  border-radius: 14px;
  background: linear-gradient(135deg, #ffffff09, #ffffff03);
  box-shadow: inset 0 1px #ffffff09;
  min-width: 104px;
}
.bb-stat small {
  display: block;
  font-size: 8px;
  letter-spacing: 2px;
  color: #9289a9;
}
.bb-stat b {
  font: 700 24px var(--num);
  color: #eee5f9;
}
.bb-stat:first-child b {
  color: var(--gold);
}
#tap-btn {
  height: 70px;
  width: 320px;
  min-width: 160px;
  flex-shrink: 0;
  overflow: hidden;
  border-radius: 999px;
  background: linear-gradient(110deg, #ff6b9d, #d64dd7 70%, #a43ef5);
  border: 1px solid #ffc5e244;
  box-shadow:
    inset 0 2px #ffffff40,
    inset 0 -4px #6d1b622b,
    0 6px 26px #ff6b9d50,
    0 0 50px #c44dff15;
  font: 800 26px var(--num);
  letter-spacing: 7px;
  text-shadow: 0 2px 8px #721a7e77;
}
#tap-btn small {
  display: block;
  font: 600 8px var(--font);
  letter-spacing: 2px;
  color: #ffe6f2d9;
  margin-top: -2px;
}
#tap-btn:active,
#tap-btn.pressed {
  transform: scale(0.94);
  box-shadow:
    inset 0 2px 8px #0003,
    0 0 40px #ff6b9d99;
}
.ripple {
  position: absolute;
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: radial-gradient(circle, #fff9, #fff0);
  pointer-events: none;
  animation: ripple 0.65s ease-out both;
}
/* Dialogs */
.modal {
  position: fixed;
  inset: 0;
  z-index: 80;
  background: #03030cb3;
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition:
    opacity 0.25s var(--ease),
    visibility 0.25s;
}
.modal.open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}
.modal-card {
  position: relative;
  width: 600px;
  max-width: 100%;
  max-height: 88dvh;
  overflow: auto;
  padding: 32px;
  border-radius: 24px;
  border: 1px solid #ff6b9d33;
  background:
    radial-gradient(ellipse at 100% 0, #c44dff12, transparent 55%),
    linear-gradient(145deg, #20203e, #101020 85%);
  box-shadow:
    0 24px 90px #0009,
    0 0 40px #ff6b9d0c,
    inset 0 1px #ffffff15;
  transform: translateY(16px) scale(0.9);
  transition: transform 0.3s var(--ease);
  scrollbar-gutter: stable;
}
.modal.open .modal-card {
  transform: translateY(0) scale(1);
}
.modal-card.wide {
  width: 720px;
}
.modal-card:before {
  content: "";
  position: absolute;
  left: 25%;
  right: 25%;
  top: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, #ffa5cc99, transparent);
}
h2 {
  font-size: 24px;
  font-weight: 900;
  letter-spacing: -0.5px;
  background: linear-gradient(120deg, #fff 10%, #ffb1d0 80%);
  background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-right: 25px;
  margin-bottom: 9px;
}
h2:after {
  content: "";
  display: block;
  width: 44px;
  height: 3px;
  margin-top: 13px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--pink), var(--purple));
  box-shadow: 0 0 10px #ff6b9d55;
}
.modal-sub {
  font-size: 11px;
  color: #aaa0bc;
  margin: 10px 0 24px;
}
.modal-close {
  position: absolute;
  right: 18px;
  top: 18px;
  width: 36px;
  height: 36px;
  min-height: 36px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: linear-gradient(130deg, #ffffff12, #ffffff04);
  color: #c6bfd6;
  font-size: 13px;
  z-index: 4;
}
.btn-pink,
.btn-glass,
.btn-mini,
.si-buy,
.up-buy,
.m-claim {
  padding: 11px 22px;
  border-radius: 14px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1px;
  min-height: 44px;
}
.btn-pink,
.si-buy,
.up-buy,
.m-claim {
  background: linear-gradient(125deg, #ff6b9d, #b748d0);
  border-color: #ffc6df33;
  box-shadow:
    inset 0 1px #ffffff30,
    0 4px 16px #ff6b9d22;
}
.btn-glass,
.btn-mini {
  background: linear-gradient(145deg, #ffffff0d, #ffffff04);
  border-color: #ffffff1a;
}
.btn-mini {
  padding: 7px 12px;
  font-size: 9px;
}
.red {
  color: #ff839d;
  border-color: #ff446633;
}
.modal-btn-row,
.stub-row {
  display: flex;
  gap: 12px;
  margin-top: 24px;
}
.modal-btn-row > * {
  flex: 1;
}
.set-note,
.stub-note {
  font-size: 11px;
  color: #8b819e;
  line-height: 1.8;
  margin-top: 20px;
}
/* Economy cards */
.up-list {
  display: grid;
  gap: 10px;
  margin-top: 20px;
}
.up-item {
  display: grid;
  position: relative;
  grid-template-columns: 36px minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  column-gap: 13px;
  align-items: center;
  padding: 14px;
  border-radius: 16px;
  border: 1px solid #ffffff0d;
  background: linear-gradient(120deg, #ffffff08, #ffffff03);
  box-shadow: inset 0 1px #ffffff07;
  transition:
    background 0.25s,
    box-shadow 0.25s;
}
.up-item:before {
  content: "↗";
  display: grid;
  place-items: center;
  grid-column: 1;
  grid-row: 1/3;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: linear-gradient(140deg, #ff6b9d2d, #c44dff22);
  box-shadow: inset 0 1px #ffffff18;
  color: #ffaaca;
  font: 700 22px var(--num);
}
.up-item:nth-child(n + 5):before {
  content: "◈";
  color: #8be8ff;
  background: linear-gradient(140deg, #00d4ff20, #c44dff22);
}
.up-name {
  grid-column: 2;
  grid-row: 1;
  font-size: 12px;
  font-weight: 800;
}
.up-name .lv {
  font: 700 11px var(--num);
  color: var(--pink);
  margin-left: 9px;
}
.up-eff {
  grid-column: 2;
  grid-row: 2;
  font-size: 9px;
  line-height: 1.5;
  color: #9d94ae;
}
.up-buy {
  grid-column: 3;
  grid-row: 1/3;
  font: 700 16px var(--num);
  letter-spacing: 0.4px;
  padding: 8px 14px;
  min-width: 90px;
  color: #fff1b1;
}
.up-buy:disabled,
.si-buy:disabled {
  color: #ff8d9e;
  background: linear-gradient(120deg, #43303a, #292333);
  border-color: #ff44661a;
  opacity: 0.65;
  box-shadow: inset 0 1px #ffffff06;
}
.up-item.locked {
  opacity: 0.48;
}
.shop-sec {
  font-size: 9px;
  letter-spacing: 2.5px;
  color: #a399b5;
  margin: 25px 0 12px;
}
.shop-grid {
  display: grid;
  gap: 10px;
}
.shop-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  border: 1px solid #ffffff12;
  border-radius: 16px;
  padding: 16px;
  background: linear-gradient(125deg, #ffffff08, #ffffff03);
  box-shadow: inset 0 1px #ffffff09;
}
.si-name {
  font-size: 12px;
  font-weight: 800;
}
.si-desc {
  font-size: 10px;
  color: #9e93b0;
  margin-top: 4px;
}
.si-buy {
  flex-shrink: 0;
  font: 700 16px var(--num);
  color: #fff2ba;
  min-width: 85px;
  letter-spacing: 0;
}
.owned .si-buy {
  color: #9ef3ce;
}
.gold {
  background: linear-gradient(130deg, #a17c25, #63522d);
}
.prestige-box {
  margin-top: 26px;
  padding: 22px;
  border-radius: 20px;
  background:
    radial-gradient(ellipse at top right, #ffd70012, transparent),
    linear-gradient(130deg, #292336, #1a1727);
  border: 1px solid #ffd7002b;
  box-shadow:
    inset 0 1px #fff5ba0e,
    0 5px 24px #0003;
}
.pb-title {
  font: 700 18px var(--num);
  letter-spacing: 2px;
  color: #ffe082;
}
.pb-req {
  display: block;
  font: 600 10px var(--font);
  letter-spacing: 0;
  color: #ac9a7c;
  margin: 5px 0 12px;
}
.pb-desc {
  font-size: 11px;
  color: #b8aeba;
  line-height: 1.8;
}
.pb-gain {
  margin: 15px 0;
  font: 700 24px var(--num);
  color: var(--gold);
}
#btn-prestige {
  width: 100%;
  background: linear-gradient(120deg, #b68c34, #8c5b41);
  box-shadow:
    inset 0 1px #fff7,
    0 4px 20px #ffd70019;
}
#modal-prestige h2 {
  background-image: linear-gradient(110deg, #fff4ca, #ffaa00);
}
#modal-prestige .modal-card {
  border-color: #ffd70033;
  box-shadow:
    0 24px 90px #0009,
    0 0 50px #ffd7000c;
}
.prestige-preview {
  padding: 20px;
  margin-top: 24px;
  border-radius: 16px;
  border: 1px solid #ffd70022;
  background: linear-gradient(130deg, #ffd70010, #ff6b9d08);
  font: 700 22px var(--num);
  text-align: center;
  color: #ffe4a1;
}
.keep-list {
  list-style: none;
  display: grid;
  gap: 10px;
  font-size: 11px;
  color: #bdb1ca;
}
.keep-list li {
  padding: 9px 12px;
  border-radius: 12px;
  background: linear-gradient(120deg, #ffffff07, #ffffff02);
}
#prestige-confirm {
  background: linear-gradient(120deg, #d8a942, #c66f56);
  box-shadow: 0 4px 20px #ffd70022;
}
/* Missions and rewards */
.streak-box {
  padding: 16px;
  margin: 23px 0;
  border-radius: 16px;
  background: linear-gradient(120deg, #ffb44414, #ff6b9d08);
  border: 1px solid #ffb44420;
  font-size: 12px;
}
.pill {
  display: inline-block;
  padding: 4px 9px;
  border-radius: 999px;
  background: linear-gradient(130deg, #ffffff0f, #ffffff05);
  font-size: 9px;
  color: #ffd586;
  margin-left: 6px;
}
.mission-list {
  display: grid;
  gap: 12px;
}
.mission {
  padding: 17px;
  border-radius: 16px;
  border: 1px solid #ffffff12;
  background: linear-gradient(125deg, #ffffff08, #ffffff03);
}
.m-head,
.m-foot {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  font-size: 11px;
}
.m-reward {
  font: 700 16px var(--num);
  color: var(--gold);
}
.m-bar {
  height: 6px;
  margin: 13px 0;
  border-radius: 999px;
  background: #0a0919;
  overflow: hidden;
  box-shadow: inset 0 1px 4px #0005;
}
.m-fill {
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--pink), var(--purple));
  transition: width 0.4s;
}
.m-prog {
  color: #9287a4;
  font: 700 12px var(--num);
}
.m-claim {
  min-height: 32px;
  padding: 6px 12px;
  font-size: 9px;
}
.mission.done {
  opacity: 0.6;
}
.daily-card,
.offline-card {
  text-align: center;
  width: 460px;
}
.daily-card h2,
.offline-card h2 {
  margin-right: 0;
}
.daily-card h2:after,
.offline-card h2:after {
  margin: 13px auto;
}
.daily-icon {
  width: 94px;
  height: 94px;
  margin: 5px auto 20px;
  display: grid;
  place-items: center;
  font-size: 44px;
  border-radius: 50%;
  background: radial-gradient(circle, #ffce6733, #ff6b9d08);
  box-shadow:
    0 0 50px #ffd7000d,
    inset 0 1px #ffd70026;
}
.daily-streak,
.offline-away {
  color: #b4a5c5;
  font-size: 12px;
  margin-top: 16px;
}
.daily-rewards,
.offline-gain {
  font: 700 44px var(--num);
  color: #ffe18b;
  text-shadow: 0 0 22px #ffd70044;
  margin: 25px 0;
}
.daily-card .btn-pink,
.offline-card .btn-pink {
  width: 100%;
  margin-top: 8px;
}
.calendar-preview {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 6px;
  margin-top: 24px;
}
.calendar-day {
  padding: 9px 2px;
  border-radius: 12px;
  background: linear-gradient(145deg, #ffffff09, #ffffff03);
  border: 1px solid #ffffff12;
  font-size: 9px;
  color: #9c8dac;
}
.calendar-day span {
  display: block;
  margin-top: 6px;
  font-size: 15px;
}
.calendar-day.current {
  background: linear-gradient(135deg, #ff6b9d33, #c44dff19);
  border-color: #ff6b9d66;
  color: #fff;
  box-shadow: 0 0 16px #ff6b9d16;
}
/* Gacha theater */
.gacha-banner {
  position: relative;
  min-height: 180px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-start;
  overflow: hidden;
  margin: 24px 0;
  padding: 24px;
  border-radius: 20px;
  border: 1px solid #ffd7002b;
  background:
    linear-gradient(90deg, #1b152ffa, #20152a66 55%, #231a3755),
    url("../assets/characters/costume_bunny.webp") 92% 18% / auto 270% no-repeat,
    radial-gradient(ellipse at top right, #ad795b, #332041);
  box-shadow:
    inset 0 1px #fff2,
    0 8px 24px #0003;
  font-size: 10px;
  color: #c8b6d4;
}
.banner-kicker {
  color: #ffe08a;
  font-size: 9px;
  letter-spacing: 3px;
  margin-bottom: 12px;
}
.gacha-banner b {
  font-size: 25px;
  line-height: 1.3;
  color: #fff1d8;
  max-width: 65%;
  font-weight: 900;
}
.banner-copy {
  font-size: 10px;
  color: #cfb7d3;
  margin-top: 10px;
  max-width: 60%;
}
.pity-row {
  display: flex;
  gap: 8px;
  margin: 18px 0;
}
.pity {
  flex: 1;
  border-radius: 12px;
  padding: 10px;
  background: linear-gradient(120deg, #ffffff0a, #ffffff03);
  border: 1px solid #ffffff12;
  text-align: center;
  font-size: 10px;
  color: #a99aba;
}
.pity b {
  font: 700 18px var(--num);
  color: #f5d2ff;
  margin-left: 4px;
}
.gacha-buttons {
  display: flex;
  gap: 12px;
}
.gacha-buttons button {
  flex: 1;
  min-height: 66px;
  font: 700 21px var(--num);
  letter-spacing: 2px;
}
.gacha-buttons small {
  font: 600 9px var(--font);
  letter-spacing: 0;
  color: #ebcce4;
}
.gacha-owned {
  font-size: 10px;
  letter-spacing: 2px;
  text-align: center;
  color: #a99ab9;
  margin-top: 22px;
}
.reveal-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(100px, 1fr));
  gap: 14px;
  margin: 28px 0;
  perspective: 1200px;
}
.reveal-card {
  position: relative;
  aspect-ratio: 3/4;
  border-radius: 16px;
  transform-style: preserve-3d;
  transition: transform 1s var(--spring);
  transform: rotateY(180deg) translateY(25px);
  --rarity: #9292a5;
}
.reveal-card.flipped {
  transform: rotateY(0) translateY(0);
}
.reveal-card.SR {
  --rarity: #c44dff;
}
.reveal-card.R {
  --rarity: #60adff;
}
.reveal-card.SSR {
  --rarity: #ffd700;
}
.reveal-card .inner,
.reveal-card .back {
  position: absolute;
  inset: 0;
  overflow: hidden;
  border-radius: 16px;
  backface-visibility: hidden;
  border: 1px solid color-mix(in srgb, var(--rarity), transparent 40%);
  box-shadow:
    0 0 24px color-mix(in srgb, var(--rarity), transparent 85%),
    inset 0 1px #ffffff22;
  background:
    radial-gradient(
      ellipse at top,
      color-mix(in srgb, var(--rarity), transparent 80%),
      transparent
    ),
    linear-gradient(150deg, #28213f, #11101f);
}
.reveal-card .back {
  transform: rotateY(180deg);
  display: grid;
  place-items: center;
  font-size: 30px;
  background:
    repeating-linear-gradient(45deg, #ffffff03 0 1px, transparent 1px 12px),
    linear-gradient(135deg, #32214c, #131324);
}
.reveal-card .inner img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.reveal-card .rr {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  text-align: center;
  padding: 22px 6px 12px;
  background: linear-gradient(transparent, #0c0a19fa);
  font-size: 9px;
  line-height: 1.5;
}
.reveal-card:not(.dup) .inner:after {
  content: "NEW";
  position: absolute;
  top: 9px;
  right: 7px;
  padding: 3px 7px;
  border-radius: 999px;
  background: linear-gradient(120deg, #ff6b9d, #b64cea);
  box-shadow: 0 0 12px #ff6b9d55;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 1px;
}
.dup-tag {
  position: absolute;
  left: 0;
  right: 0;
  top: 10px;
  text-align: center;
  color: #ffe186;
  font: 700 10px var(--num);
  background: #121023aa;
}
.reveal-card.SSR.flipped {
  animation: rareGlow 2s infinite;
}
.reveal-card.SSR.flipped:after {
  content: "✦";
  position: absolute;
  inset: -15%;
  font-size: 80px;
  text-align: center;
  color: #ffd70077;
  pointer-events: none;
  animation: confetti 1.2s ease-out both;
  z-index: -1;
}
#reveal-close {
  width: 100%;
}
/* Inventory and settings */
.inv-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
  margin-top: 24px;
}
.inv-item {
  border-radius: 18px;
  overflow: hidden;
  border: 1px solid #ffffff12;
  background: linear-gradient(135deg, #ffffff09, #ffffff02);
  cursor: pointer;
  transition:
    transform 0.25s,
    box-shadow 0.25s;
}
.inv-item.equipped {
  border-color: #ff6b9d88;
  box-shadow: 0 0 20px #ff6b9d22;
}
.inv-img {
  height: 180px;
  background: radial-gradient(ellipse at center, #c44dff11, transparent);
}
.inv-img img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.inv-item.locked img {
  filter: brightness(0.12);
}
.inv-name {
  padding: 10px;
  text-align: center;
  font-size: 10px;
  background: linear-gradient(transparent, #0d0d1a77);
}
.set-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 18px 0;
  border-bottom: 1px solid #ffffff08;
  font-size: 12px;
}
.set-val {
  display: block;
  font: 700 13px var(--num);
  color: var(--pink);
  margin-top: 2px;
}
.slider {
  width: 45%;
  accent-color: var(--pink);
  height: 5px;
  border-radius: 999px;
  cursor: pointer;
}
.toggle {
  width: 46px;
  height: 27px;
  min-height: 27px;
  border-radius: 999px;
  background: linear-gradient(#2d2841, #211c32);
  padding: 3px;
  box-shadow: inset 0 2px 5px #0004;
}
.toggle i {
  display: block;
  width: 19px;
  height: 19px;
  border-radius: 50%;
  background: linear-gradient(#e8dceb, #b7a8c5);
  box-shadow: 0 2px 7px #0004;
  transition: transform 0.25s;
}
.toggle.on {
  background: linear-gradient(110deg, #ff6b9d, #a541ce);
  box-shadow: 0 0 14px #ff6b9d22;
}
.toggle.on i {
  transform: translateX(18px);
  background: linear-gradient(#fff, #ffe9f2);
}
.theme-row {
  display: flex;
  gap: 10px;
}
.swatch {
  width: 30px;
  height: 30px;
  min-height: 30px;
  border-radius: 50%;
  background:
    radial-gradient(circle at 35% 25%, #ffffff77, transparent 55%), var(--sw);
  border: 1px solid #ffffff33;
  box-shadow: 0 2px 10px #0005;
}
.danger {
  color: #e6a0ae;
}
.friend-code {
  margin-top: 24px;
  padding: 20px;
  border-radius: 16px;
  background: linear-gradient(125deg, #ffffff09, #ffffff03);
  font-size: 11px;
}
.friend-code b {
  font: 700 24px var(--num);
  margin: 0 10px;
  color: #f3c2de;
}
/* Feedback */
#fx-layer {
  position: fixed;
  inset: 0;
  z-index: 65;
  pointer-events: none;
}
.float-txt {
  position: absolute;
  padding: 5px 13px;
  border-radius: 999px;
  background: linear-gradient(130deg, #e3ad3eee, #a06b24ee);
  border: 1px solid #fff2a655;
  box-shadow:
    0 4px 14px #0004,
    0 0 16px #ffd70022;
  font: 800 20px var(--num);
  color: #fffdf2;
  text-shadow: 0 1px 3px #68430b;
  animation: coinFloat 0.95s ease-out both;
}
.spark {
  position: absolute;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: radial-gradient(circle, #fff, #ffd700 40%, #ffd70000 75%);
  box-shadow: 0 0 8px #ffd70044;
  animation: sparkFly 0.65s ease-out both;
}
.spark:nth-child(3n) {
  background: radial-gradient(circle, #fff, #ff6b9d 40%, transparent 75%);
}
.spark:nth-child(3n + 1) {
  background: radial-gradient(circle, #fff, #c44dff 40%, transparent 75%);
}
#toast {
  position: fixed;
  right: 24px;
  top: calc(var(--hud) + env(safe-area-inset-top) + 18px);
  max-width: min(380px, 90vw);
  padding: 14px 22px;
  border-radius: 999px;
  border: 1px solid #ff6b9d33;
  background: linear-gradient(120deg, #30213bef, #17192aef);
  backdrop-filter: blur(20px);
  box-shadow:
    0 8px 25px #0005,
    0 0 20px #ff6b9d10;
  font-size: 11px;
  z-index: 110;
  opacity: 0;
  transform: translateX(120%);
  transition:
    transform 0.3s var(--spring),
    opacity 0.3s;
}
#toast.show {
  opacity: 1;
  transform: translateX(0);
}
#level-fx {
  position: fixed;
  top: 35%;
  left: 0;
  right: 0;
  z-index: 70;
  text-align: center;
  font: 700 46px var(--num);
  letter-spacing: 7px;
  color: #ffe69e;
  text-shadow:
    0 0 25px #ffd70088,
    0 3px 6px #0008;
  pointer-events: none;
  animation: levelPop 1.15s ease-out both;
}
#tier-event {
  position: absolute;
  inset: 0;
  z-index: 35;
  display: grid;
  place-items: center;
  pointer-events: none;
}
.event-flash {
  position: absolute;
  inset: 0;
  background: linear-gradient(120deg, #fff, #ffeff7);
  animation: screenFlash 0.5s ease-out both;
}
.te-card {
  text-align: center;
  padding: 25px 50px;
  border-radius: 24px;
  background: linear-gradient(135deg, #19142cda, #291a36da);
  border: 1px solid #ff6b9d44;
  box-shadow:
    0 12px 50px #0005,
    0 0 50px #ff6b9d22;
  backdrop-filter: blur(20px);
  animation: eventEnter 0.8s var(--spring) both;
}
.te-kicker {
  font-size: 9px;
  letter-spacing: 4px;
  color: #ffb5d3;
}
.te-tier {
  font: 700 52px var(--num);
  letter-spacing: 5px;
  color: #fff;
  margin: 6px 0;
}
.te-line {
  font-style: italic;
  font-size: 13px;
  color: #e7c2dd;
}
.te-place {
  font-size: 9px;
  letter-spacing: 2px;
  color: #b39bbf;
  margin-top: 14px;
}
#rotate-overlay {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 150;
  background: radial-gradient(ellipse, #2a1e3b, #0d0d1a 70%);
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 28px;
  text-align: center;
}
.rot-phone {
  width: 40px;
  height: 70px;
  border: 2px solid #ffb5d3;
  border-radius: 14px;
  box-shadow: 0 0 30px #ff6b9d33;
  animation: phoneRotate 2.4s ease-in-out infinite;
}
.rot-text {
  font-size: 18px;
}
.rot-text small {
  color: #a599b4;
}
#install-bar {
  position: fixed;
  left: 50%;
  bottom: calc(var(--footer) + env(safe-area-inset-bottom) + 15px);
  transform: translateX(-50%);
  width: min(460px, 94vw);
  display: flex;
  align-items: center;
  gap: 15px;
  z-index: 100;
  border-radius: 20px;
  padding: 15px 18px;
  background: linear-gradient(120deg, #2a203eea, #141627ee);
  backdrop-filter: blur(20px);
  border: 1px solid #ff6b9d33;
  box-shadow: 0 8px 30px #0006;
  font-size: 10px;
}
#install-btn {
  padding: 8px 14px;
  color: #ffcee3;
  font-size: 9px;
}
#install-dismiss {
  margin-left: auto;
  min-height: 32px;
  width: 32px;
  border-radius: 50%;
}
/* Motion */
@keyframes breathe {
  0%,
  100% {
    transform: translateY(0) scale(1);
  }
  50% {
    transform: translateY(-2px) scale(1.008);
  }
}
@keyframes glow {
  0%,
  100% {
    filter: drop-shadow(0 0 8px #ffd7004d);
  }
  50% {
    filter: drop-shadow(0 0 20px #ffd70099);
  }
}
@keyframes tapReact {
  30% {
    transform: translateY(3px) scale(0.98);
  }
}
@keyframes shimmer {
  0%,
  30% {
    transform: translateX(-120%);
  }
  80%,
  100% {
    transform: translateX(120%);
  }
}
@keyframes hudEnter {
  from {
    opacity: 0;
    transform: translateY(-20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes footerEnter {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes characterEnter {
  from {
    opacity: 0;
    translate: 0 22px;
  }
  to {
    opacity: 1;
    translate: 0 0;
  }
}
@keyframes railEnter {
  from {
    opacity: 0;
    translate: -25px 0;
  }
  to {
    opacity: 1;
    translate: 0 0;
  }
}
@keyframes railEnterRight {
  from {
    opacity: 0;
    translate: 25px 0;
  }
  to {
    opacity: 1;
    translate: 0 0;
  }
}
@keyframes dotPulse {
  50% {
    box-shadow:
      0 0 0 4px #ff446611,
      0 0 8px #ff4466;
  }
}
@keyframes rareGlow {
  0%,
  100% {
    box-shadow: 0 0 10px #ffd70022;
  }
  50% {
    box-shadow: 0 0 22px #ffd70055;
  }
}
@keyframes ripple {
  from {
    transform: translate(-50%, -50%) scale(0);
    opacity: 0.6;
  }
  to {
    transform: translate(-50%, -50%) scale(9);
    opacity: 0;
  }
}
@keyframes coinFloat {
  0% {
    opacity: 0;
    transform: translate(-50%, 0) scale(0.6);
  }
  15% {
    opacity: 1;
    transform: translate(-50%, -10px) scale(1.1);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -100px) scale(0.85);
  }
}
@keyframes sparkFly {
  to {
    transform: translate(var(--dx), var(--dy)) scale(0);
    opacity: 0;
  }
}
@keyframes levelPop {
  0% {
    opacity: 0;
    transform: translateY(15px) scale(0.7);
  }
  25% {
    opacity: 1;
    transform: translateY(0) scale(1.05);
  }
  75% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translateY(-50px) scale(1);
  }
}
@keyframes screenFlash {
  from {
    opacity: 0.85;
  }
  to {
    opacity: 0;
  }
}
@keyframes eventEnter {
  from {
    opacity: 0;
    transform: translateY(80px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes phoneRotate {
  0%,
  100% {
    transform: rotate(-90deg);
  }
  40%,
  70% {
    transform: rotate(0);
  }
}
@keyframes confetti {
  from {
    opacity: 1;
    transform: translateY(20px) scale(0.3) rotate(0);
  }
  to {
    opacity: 0;
    transform: translateY(-80px) scale(1.6) rotate(80deg);
  }
}
@keyframes stagger {
  from {
    opacity: 0;
    transform: translateX(-15px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}
