/* Keep effect descriptions readable on small displays. */
.up-eff {
  font-size: 10px;
}
.up-name {
  font-size: 12px;
}
@media (max-width: 767px) {
  .up-eff {
    font-size: 10px;
  }
  .up-name {
    font-size: 12px;
  }
  .up-name .lv {
    font-size: 10px;
  }
}

/* ===== ATELIER / final art-direction pass ===== */
:root {
  --hud: 64px;
  --footer: 112px;
  --label: #8888aa;
  --surface: linear-gradient(135deg, #ffffff0f, #ffffff05);
  --surface-shadow: 0 4px 24px #0005, inset 0 1px #ffffff0d;
  --space: 8px;
}
* {
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
body {
  font-family: var(--font);
  line-height: 1.5;
}
button,
input,
select,
textarea {
  font-family: var(--font);
}
[id$="-level"],
[id$="-count"],
[id$="-gems"],
[id^="pity-"],
.chip span,
.bb-stat b,
.up-cost,
.lv,
.m-prog,
.m-reward,
.pity b,
.pb-gain,
.daily-rewards,
.offline-gain,
.friend-code b,
.si-buy,
.heart-xp,
.number-value {
  font-family: var(--num);
  font-weight: 700;
  letter-spacing: 0.5px;
  font-variant-numeric: tabular-nums;
}
h2,
.te-tier {
  font: 700 28px/1.3 var(--num);
  letter-spacing: 1px;
  background: linear-gradient(110deg, #fff, #ff6b9d);
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
h2 {
  margin: 0;
}
h2:after {
  display: none;
}
.rail-heading,
.rail-head,
.shop-sec,
.bb-stat small,
.hud-caption,
.heart-label,
.section-label {
  font: 600 12px/1.5 var(--font);
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--label);
}
.modal-sub,
.si-desc,
.up-eff,
.set-note,
.stub-note {
  font: 600 12px/1.5 var(--font);
  color: var(--label);
}
#hud {
  height: calc(64px + env(safe-area-inset-top));
  gap: 24px;
  padding: calc(8px + env(safe-area-inset-top))
    max(24px, env(safe-area-inset-right)) 8px
    max(24px, env(safe-area-inset-left));
}
.avatar-ring {
  width: 40px;
  height: 40px;
  padding: 4px;
  background: conic-gradient(#ff6b9d, #c44dff, #ff6b9d);
  box-shadow: 0 0 16px #ff6b9d26;
}
.avatar-ring img {
  outline: 2px solid #151222;
}
.hud-lv {
  height: 18px;
  min-width: 18px;
  font-size: 12px;
  right: -3px;
  bottom: -3px;
}
.hud-name {
  font: 800 14px/1.3 var(--font);
  letter-spacing: 0.5px;
}
.hud-caption {
  font-size: 8px;
  margin-bottom: 0;
}
.hud-title {
  font-size: 9px;
  letter-spacing: 1.5px;
}
.hud-left {
  gap: 12px;
}
.hud-center {
  position: relative;
  max-width: 30vw;
  width: 280px;
}
.heart-label {
  font-size: 9px;
  margin-bottom: 0;
}
.heart-bar {
  height: 24px;
}
.heart-bar:before {
  font-size: 16px;
  top: -1px;
}
.heart-xp {
  position: absolute;
  right: 0;
  top: 100%;
  font-size: 9px;
  line-height: 1;
  margin: 2px 0 0;
}
.bar-level {
  font: 700 15px var(--num);
  letter-spacing: 0.5px;
}
#heart-fill:after {
  animation-duration: 3s;
}
.chip {
  height: 32px;
  padding: 0 12px;
  gap: 6px;
  min-width: 88px;
  background: linear-gradient(135deg, #ffffff0d, #ffffff04);
  border: 1px solid #ffffff14;
}
.chip span {
  font-size: 20px;
}
.chip .ui-icon {
  width: 16px;
  height: 16px;
}
.notification-dot {
  width: 8px;
  height: 8px;
  animation: notificationPulse 2s infinite;
}
.circle-btn {
  width: 36px;
  height: 36px;
  min-height: 36px;
  background: linear-gradient(135deg, #ffffff06, #ffffff00);
  box-shadow: none;
  border-color: transparent;
  color: #8888aa;
}
.hud-actions {
  gap: 8px;
}
#hud:after {
  background: linear-gradient(90deg, transparent, #ff6b9d4d, transparent);
}
/* Softer lighting, local reflections, crisp value feedback. */
.bg-vignette {
  background:
    radial-gradient(ellipse at center, transparent 20%, #0006 100%),
    linear-gradient(0deg, #0d0d1a99, transparent 30%);
}
#character-wrap:before {
  width: 300px;
  height: 300px;
  inset: auto;
  left: 50%;
  top: 28%;
  transform: translateX(-50%);
  background: radial-gradient(ellipse, #ff6b9d26, transparent 70%);
  filter: blur(80px);
}
.character-stack {
  transition: opacity 0.6s var(--ease);
}
.bg-layer {
  transition: opacity 0.8s var(--ease);
}
.layer {
  -webkit-box-reflect: below -2px linear-gradient(transparent 88%, #ffffff1a);
}
#character-wrap {
  bottom: 8px;
}
.stage-caption {
  top: 16px;
}
.stage-corner {
  left: 248px;
  font-size: 9px;
}
.float-txt {
  font: 700 20px var(--num);
  letter-spacing: 0.5px;
  animation: premiumCoin 0.95s ease-out both;
}
.spark {
  animation-duration: 0.6s;
}
.spark:nth-child(2n) {
  width: 4px;
  height: 4px;
}
.spark:nth-child(3n) {
  width: 10px;
  height: 10px;
}
.spark:nth-child(5n) {
  width: 12px;
  height: 12px;
}
#bubble {
  padding: 16px 16px 16px 48px;
  font-size: 13px;
  line-height: 1.5;
  transition:
    opacity 0.4s,
    transform 0.4s;
  transition-delay: 0.2s;
}
.event-flash {
  animation-duration: 0.2s;
}
.te-card {
  animation-delay: 0.2s;
}
.te-tier {
  font-size: 48px;
}
.te-kicker {
  font-size: 12px;
}
.te-place {
  font-size: 12px;
}
.te-line {
  font-size: 16px;
}
/* Consistent surfaces and eight-point rhythm. */
.rail-btn,
.up-item,
.shop-item,
.mission,
.inv-item,
.set-row,
.calendar-day,
.pity,
.bb-stat,
.friend-code {
  border: 1px solid #ffffff14;
  border-top-color: #ffffff26;
  background: var(--surface);
  border-radius: 16px;
  box-shadow: var(--surface-shadow);
}
#left-rail,
#right-rail,
.modal-card,
#bubble,
#boost-pill {
  backdrop-filter: blur(12px);
}
#left-rail {
  padding: 16px;
  gap: 8px;
  left: 24px;
  top: 24px;
  bottom: 24px;
}
.rail-heading {
  padding: 0 8px 8px;
  font-size: 10px;
}
.rail-heading b {
  font: 700 24px/1.3 var(--num);
  color: #fff;
}
.rail-btn {
  padding: 8px 12px;
  gap: 12px;
  min-height: 56px;
  font-size: 13px;
}
.rail-btn .ico {
  width: 40px;
  height: 40px;
}
.rail-foot {
  font-size: 9px;
  line-height: 1.6;
  padding: 16px 8px 0;
}
.rail-head {
  font-size: 13px;
  margin: 0 0 16px;
}
.rail-head small {
  font-size: 10px;
}
.rail-toggle.right {
  display: flex;
}
.rail-toggle {
  background: linear-gradient(135deg, #252039cc, #111322cc);
  backdrop-filter: blur(12px);
}
#right-rail {
  width: min(560px, calc(100vw - 32px));
  right: 16px;
  top: 80px;
  bottom: 16px;
  padding: 24px;
  transform: translateX(calc(100% + 24px));
  animation: none;
}
#right-rail.open {
  transform: translateX(0);
}
#costume-list {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  padding: 4px;
}
.costume-thumb {
  height: auto;
  aspect-ratio: 3/4;
  border-radius: 16px;
}
.costume-thumb img {
  object-fit: cover;
  object-position: center 14%;
  width: 100%;
  height: 100%;
}
.costume-thumb:after {
  inset: 60% 0 0;
  background: linear-gradient(transparent, #000c);
}
.costume-name {
  font: 800 13px/1.3 var(--font);
  left: 8px;
  right: 8px;
  bottom: 12px;
}
.costume-thumb.locked img {
  filter: brightness(0.45);
}
.lock {
  background: linear-gradient(135deg, #0007, #000a);
  backdrop-filter: blur(4px);
}
.lock:after {
  width: 32px;
  height: 32px;
  opacity: 0.5;
  background: #fff;
}
.costume-thumb .rar {
  width: 8px;
  height: 8px;
  overflow: hidden;
  padding: 0;
  font-size: 0;
  background: #aaaabb;
  border-radius: 50%;
  top: 12px;
  left: 12px;
  box-shadow: 0 0 8px currentColor;
}
.costume-thumb .rar.R {
  background: #60b8ff;
}
.costume-thumb .rar.SR {
  background: #c44dff;
}
.costume-thumb .rar.SSR {
  background: #ffd700;
}
.costume-thumb.equipped {
  outline: 1px solid var(--pink);
  outline-offset: -2px;
  transform: scale(1.02);
}
.inv-grid {
