/* Dialog architecture: fixed header/footer, independent scrolling body. */
.modal {
  background: #0009;
  backdrop-filter: blur(8px);
  transition:
    opacity 0.2s,
    visibility 0.2s;
}
.modal-card,
.modal-card.wide {
  width: 560px;
  max-width: calc(100vw - 32px);
  max-height: 90dvh;
  padding: 0;
  border-radius: 24px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  scrollbar-gutter: auto;
  background: linear-gradient(180deg, #1a1a3e, #0d0d1a);
  border: 1px solid #ff6b9d26;
  box-shadow:
    0 8px 48px #0008,
    0 0 80px #ff6b9d1a;
  transform: scale(0.92);
  transition:
    transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
    opacity 0.2s;
}
.modal.open .modal-card {
  transform: scale(1);
}
.modal-card:before {
  display: none;
}
.dialog-header {
  position: relative;
  padding: 24px 24px 16px;
  flex-shrink: 0;
  text-align: center;
}
.dialog-header:after {
  content: "";
  display: block;
  width: 60px;
  height: 2px;
  border-radius: 999px;
  margin: 12px auto 0;
  background: linear-gradient(
    90deg,
    transparent,
    #ff6b9d,
    #c44dff,
    transparent
  );
}
.dialog-header h2 {
  padding: 0 24px;
}
.modal-close {
  top: 16px;
  right: 16px;
  width: 32px;
  height: 32px;
  min-height: 32px;
  border-radius: 50%;
  padding: 0;
  font-size: 12px;
}
.dialog-body {
  padding: 0 24px 24px;
  overflow-y: auto;
  max-height: 60dvh;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}
.dialog-footer {
  padding: 16px 24px;
  flex-shrink: 0;
  border-top: 1px solid #ffffff0f;
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  background: linear-gradient(135deg, #ffffff04, #ffffff00);
}
.dialog-footer > .btn-pink {
  min-width: 136px;
}
.dialog-footer .modal-btn-row {
  margin: 0;
  flex: 1;
}
.modal-sub {
  margin: 0 0 24px;
}
.modal-btn-row {
  gap: 12px;
  margin: 0;
}
.daily-card .dialog-header,
.offline-card .dialog-header {
