.reveal-card {
  transition: transform 0.8s var(--spring);
}
.reveal-card.N .inner {
  box-shadow: inset 0 1px #ffffff15;
}
.reveal-card.SR.flipped {
  animation: srPulse 1.8s ease-in-out infinite;
}
.reveal-card.R.flipped .inner {
  box-shadow: 0 0 20px #60adff22;
}
.reveal-card:not(.dup) .inner:after {
  background: linear-gradient(135deg, #ff4466, #e66699);
  animation: badgeBounce 0.5s var(--spring) both;
  animation-delay: 1s;
}
.reveal-card.SSR.flipped:before {
  content: "";
  position: absolute;
  inset: -45%;
  border-radius: 50%;
  z-index: -1;
  background: radial-gradient(ellipse, #ffd70077, transparent 68%);
  animation: goldBurst 0.8s ease-out both;
}
.ssr-shake .modal-card {
