/* Prestige theater and preferences */
.prestige-preview {
  display: none;
}
.prestige-comparison {
  display: grid;
  grid-template-columns: 1fr 24px 1fr;
  gap: 12px;
  margin: 16px 0 24px;
  text-align: left;
}
.prestige-column {
  padding: 16px;
  border-radius: 16px;
  border: 1px solid #ffffff14;
  background: var(--surface);
}
.prestige-column small {
  font: 600 11px var(--font);
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: #8888aa;
}
.prestige-column strong {
  font: 700 24px var(--num);
  display: block;
  color: #aaaacc;
  margin-top: 8px;
}
.prestige-column.after {
  border-color: #ffd70033;
  background: linear-gradient(135deg, #ffd70012, #ffd70004);
}
.prestige-column.after strong {
  color: #ffd700;
}
.prestige-arrow {
  align-self: center;
  text-align: center;
  font: 700 24px var(--num);
  color: #a78b53;
}
.prestige-gem {
