  width: 72px;
  height: 72px;
  display: grid;
  place-items: center;
  margin: 8px auto 16px;
  font-size: 52px;
  color: #ffd700;
}
.prestige-gem:before {
  content: "";
  position: absolute;
  inset: -16px;
  border-radius: 50%;
  background: conic-gradient(
    transparent,
    #ffd70033,
    transparent,
    #ff6b9d22,
    transparent
  );
  filter: blur(12px);
  animation: gemOrbit 8s linear infinite;
}
.prestige-warning {
  color: #ff4466;
  font-style: italic;
