  font: 700 16px var(--num);
  letter-spacing: 1px;
  touch-action: none;
  user-select: none;
}
#prestige-confirm:before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(90deg, #ffffff33, #ffd70044);
  transform: scaleX(0);
  transform-origin: left;
}
#prestige-confirm.holding:before {
  transform: scaleX(1);
  transition: transform 2s linear;
}
#prestige-confirm .hold-caption {
  display: block;
  font: 600 9px var(--font);
  letter-spacing: 1px;
