}
.set-val {
  font: 700 13px var(--num);
}
.toggle {
  height: 28px;
  min-height: 28px;
  width: 48px;
  border-radius: 999px;
}
.toggle i {
  width: 20px;
  height: 20px;
}
.toggle.on i {
  transform: translateX(20px);
}
.slider {
  -webkit-appearance: none;
  appearance: none;
  height: 6px;
  border: 0;
  background: linear-gradient(90deg, #ff6b9d, #c44dff);
  box-shadow: inset 0 1px #ffffff22;
  outline-offset: 8px;
}
.slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: linear-gradient(#fff, #ffadd0);
  box-shadow: 0 0 12px #ff6b9d88;
  cursor: pointer;
}
.slider::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border: 0;
  border-radius: 50%;
  background: #ffd8e8;
  box-shadow: 0 0 12px #ff6b9d88;
}
.theme-row {
  gap: 8px;
}
.swatch {
  position: relative;
  width: 56px;
  height: 44px;
  min-height: 44px;
  border-radius: 12px;
  background:
    linear-gradient(145deg, #ffffff18, #ffffff00),
    linear-gradient(25deg, #12122a 40%, var(--sw));
  border: 1px solid #ffffff1f;
}
.swatch[aria-pressed="true"] {
  border-color: #ff6b9d;
  box-shadow: 0 0 12px #ff6b9d33;
}
.swatch:after {
  content: attr(aria-label);
  position: absolute;
  bottom: 3px;
  left: 0;
  right: 0;
  color: #fff;
  font: 700 8px var(--font);
  text-transform: uppercase;
