  font: 600 10px var(--font);
  color: #666688;
  letter-spacing: 1.5px;
  margin-top: 16px;
}
.image-ready {
  animation: imageFade 0.3s var(--ease) both;
}
.mission {
  padding: 16px;
}
.m-head {
  font-size: 13px;
}
.m-foot {
  font-size: 12px;
}
.m-bar {
  margin: 16px 0;
}
.streak-box {
  padding: 16px;
  margin: 0 0 24px;
  font-size: 13px;
}
.friend-code {
  padding: 16px;
  margin: 0;
}
.stub-note {
  margin-top: 16px;
}
.stub-row {
  margin-top: 16px;
  gap: 12px;
}
.stub-row button {
  padding: 12px;
}
.set-note a {
  color: #aaaacc;
}
@keyframes notificationPulse {
  50% {
    transform: scale(1.3);
    box-shadow: 0 0 10px #ff446688;
  }
}
@keyframes premiumCoin {
  0% {
    opacity: 0;
    transform: translate(-50%, 0) scale(0);
  }
  18% {
    opacity: 1;
    transform: translate(-50%, -12px) scale(1.2);
  }
  32% {
    transform: translate(-50%, -20px) scale(1);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -80px) scale(1);
  }
}
@keyframes flame {
  25% {
    transform: rotate(-5deg) scaleY(1.08);
  }
  70% {
    transform: rotate(4deg) scaleY(0.94);
  }
}
@keyframes srPulse {
  50% {
    filter: drop-shadow(0 0 14px #c44dff77);
  }
}
@keyframes goldBurst {
  from {
    opacity: 0;
    scale: 0.4;
  }
  30% {
    opacity: 1;
  }
  to {
    opacity: 0.4;
    scale: 1.2;
  }
}
@keyframes screenShake {
  25% {
    translate: 2px 0;
  }
  50% {
    translate: -2px 1px;
  }
  75% {
    translate: 1px -1px;
  }
}
@keyframes badgeBounce {
  from {
    translate: 0 -10px;
    scale: 0.7;
  }
  60% {
    translate: 0 0;
    scale: 1.1;
  }
  to {
    translate: 0 0;
    scale: 1;
  }
}
@keyframes gemOrbit {
  to {
    rotate: 360deg;
  }
}
@keyframes imageFade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes premiumConfetti {
  0% {
    opacity: 0;
    transform: translate(0, 0) rotate(0);
  }
  15% {
    opacity: 1;
  }
  60% {
    transform: translate(var(--cx), var(--cy)) rotate(180deg);
  }
  100% {
    opacity: 0;
    transform: translate(var(--cx), calc(var(--cy) + 130px)) rotate(300deg);
  }
}
