/* Full touch boxes around compact visual tracks. */
.number-value {
  display: inline-block;
}
.toggle {
  position: relative;
  height: 44px;
  min-height: 44px;
  width: 52px;
  padding: 0 4px;
  display: flex;
  align-items: center;
  background: none !important;
  border: 0;
  box-shadow: none !important;
}
.toggle:before {
  content: "";
  position: absolute;
  inset: 8px 0;
  border-radius: 999px;
  background: linear-gradient(#2d2841, #211c32);
  box-shadow: inset 0 2px 5px #0004;
}
.toggle.on:before {
  background: linear-gradient(135deg, #ff6b9d, #c44dff);
}
.toggle i {
  position: relative;
  z-index: 1;
}
.toggle.on i {
  transform: translateX(24px);
}
.slider {
  height: 44px;
  background: transparent;
  box-shadow: none;
}
.slider::-webkit-slider-runnable-track {
  height: 6px;
  border-radius: 999px;
  background: linear-gradient(90deg, #ff6b9d, #c44dff);
}
.slider::-webkit-slider-thumb {
  margin-top: -6px;
}
.slider::-moz-range-track {
  height: 6px;
  border-radius: 999px;
  background: linear-gradient(90deg, #ff6b9d, #c44dff);
}
.modal-close {
  width: 44px;
  height: 44px;
  min-height: 44px;
}
.daily-streak {
  display: inline-block;
}
.streak-flame {
  font-size: 22px;
  margin-right: 4px;
}
@media (max-width: 767px) {
  .up-item {
    grid-template-columns: 40px minmax(0, 1fr) 64px;
    gap: 0 12px;
    min-height: 112px;
  }
  .up-item:before {
    grid-column: 1;
    grid-row: 1/3;
  }
  .up-name {
    grid-column: 2;
    grid-row: 1;
    font-size: 14px;
  }
  .up-eff {
    grid-column: 2;
    grid-row: 2;
    font-size: 12px;
  }
  .up-action {
    grid-column: 3;
    grid-row: 1/3;
    gap: 4px;
  }
  .dialog-header {
    padding-top: 24px;
  }
}
.prestige-gem .ui-icon {
  width: 48px;
  height: 48px;
  stroke-width: 1.3;
  filter: drop-shadow(0 0 16px #ffd70066);
}
